select * from customer;

-- 1. Revenue Analysis
-- compared total revenue generated by make and female customers

SELECT gender, SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY gender;

-- 2. Discount & Spending Analysis
-- Identified discount users whose purchase amounts were at or above the overall average

SELECT customer_id, purchase_amount 
FROM customer
WHERE discount_applied= 'Yes' 
	AND purchase_amount >= (SELECT AVG(purchase_amount) FROM customer);

-- 3. Product Rating Analysis
-- Rank the top 5 products by average review rating.

SELECT item_purchased,
	ROUND(AVG(review_rating)::numeric,2) AS "Average Product Rating"
FROM customer
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC
LIMIT 5;

-- 4. Shipping Analysis
-- Compared average purchase amounts for Standard and Express shipping.

SELECT shipping_type, 
	ROUND(AVG(purchase_amount),2)
FROM customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type;

--5. Subscription Analysis
-- Compared customer counts, average spending and total revenue between subcribers non-subscribers.

SELECT subscription_status,
COUNT(customer_id) AS total_customer,
ROUND(AVG(purchase_amount),2) AS avg_spend,
ROUND(SUM(purchase_amount),2) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue, avg_spend DESC;

--6. Discount Dependency Analysis
-- Identified the top 5 products by percentage of purchases with discounts applied.

SELECT item_purchased,
ROUND(100*SUM(
	CASE WHEN discount_applied = 'Yes' then 1
	ELSE 0 END )/COUNT(*),2)
	AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate desc
LIMIT 5;

-- 7. Customer Segmentation
-- Classified customers into New, Returning, and Loyal segments based on previous purchased

WITH customer_type AS (
SELECT customer_id,
	previous_purchases,
	CASE WHEN previous_purchases=1 then 'New'
	WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
	ELSE 'Loyal'
	END AS customer_segment
	FROM customer)
SELECT customer_segment,
COUNT(*) AS number_of_customers
FROM customer_type
GROUP BY customer_segment;

-- 8. Product Popularity Analysis
-- Identified the top 3 most purchased products within each category.

WITH item_counts AS (
SELECT category, 
	item_purchased,
	COUNT(customer_id) AS total_orders,
	ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
FROM customer
GROUP BY category,item_purchased
)
SELECT item_rank,
	category,
	item_purchased,
	total_orders
FROM item_counts
WHERE item_rank <= 3;

--9 Repeat Buyer Analysis
-- Compared subcription status among customers with more then 5 previous purchases.

SELECT subscription_status,
COUNT(customer_id) AS repeated_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

-- 10. Age Group Revenue Analysis
-- Compared total revenue across customer age groups.

SELECT age_group,
	SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue DESC;

